   251	otError Commissioner::AddJoiner(const Mac::ExtAddress *aEui64, const char *aPskd, uint32_t aTimeout)
   252	{
   253	    otError error = OT_ERROR_NO_BUFS;
   254	
   255	    VerifyOrExit(mState == OT_COMMISSIONER_STATE_ACTIVE, error = OT_ERROR_INVALID_STATE);
   256	
   257	    VerifyOrExit(strlen(aPskd) <= Dtls::kPskMaxLength, error = OT_ERROR_INVALID_ARGS);
   258	    RemoveJoiner(aEui64, 0); // remove immediately
   259	
   260	    for (Joiner *joiner = &mJoiners[0]; joiner < OT_ARRAY_END(mJoiners); joiner++)
   261	    {
   262	        if (joiner->mValid)
   263	        {
   264	            continue;
   265	        }
   266	
   267	        if (aEui64 != NULL)
   268	        {
   269	            joiner->mEui64 = *aEui64;
   270	            joiner->mAny   = false;
   271	        }
   272	        else
   273	        {
   274	            joiner->mAny = true;
   275	        }
   276	
   277	        (void)strlcpy(joiner->mPsk, aPskd, sizeof(joiner->mPsk));
   278	        joiner->mValid          = true;
   279	        joiner->mExpirationTime = TimerMilli::GetNow() + Time::SecToMsec(aTimeout);
