   490	otError Commissioner::SendMgmtCommissionerGetRequest(const uint8_t *aTlvs, uint8_t aLength)
   491	{
   492	    otError          error = OT_ERROR_NONE;
   493	    Coap::Message *  message;
   494	    Ip6::MessageInfo messageInfo;
   495	    MeshCoP::Tlv     tlv;
   496	
   497	    VerifyOrExit((message = NewMeshCoPMessage(Get<Coap::Coap>())) != NULL, error = OT_ERROR_NO_BUFS);
   498	
   499	    SuccessOrExit(error = message->Init(OT_COAP_TYPE_CONFIRMABLE, OT_COAP_CODE_POST, OT_URI_PATH_COMMISSIONER_GET));
   500	
   501	    if (aLength > 0)
   502	    {
   503	        SuccessOrExit(error = message->SetPayloadMarker());
   504	    }
   505	
   506	    if (aLength > 0)
   507	    {
   508	        tlv.SetType(MeshCoP::Tlv::kGet);
   509	        tlv.SetLength(aLength);
   510	        SuccessOrExit(error = message->Append(&tlv, sizeof(tlv)));
   511	        SuccessOrExit(error = message->Append(aTlvs, aLength));
   512	    }
   513	
   514	    messageInfo.SetSockAddr(Get<Mle::MleRouter>().GetMeshLocal16());
   515	    SuccessOrExit(error = Get<Mle::MleRouter>().GetLeaderAloc(messageInfo.GetPeerAddr()));
   516	    messageInfo.SetPeerPort(kCoapUdpPort);
   517	    SuccessOrExit(error = Get<Coap::Coap>().SendMessage(*message, messageInfo,
   518	                                                        Commissioner::HandleMgmtCommissionerGetResponse, this));
   519	
   520	    otLogInfoMeshCoP("sent MGMT_COMMISSIONER_GET.req to leader");
   521	
   522	exit:
   523	
   524	    if (error != OT_ERROR_NONE && message != NULL)
   525	    {
   526	        message->Free();
   527	    }
   528	
   529	    return error;
   530	}
